    if horizontal is not None:
        top_h = horizontal
        bottom_h = h - horizontal - 1
        height = min(top_h, bottom_h)
        if vertical is None:
            for i in range(height):
                out[horizontal - 1 - i] = grid[horizontal + 1 + i][:]
        else:
            left_w, right_w = vertical, w - vertical - 1
            width = min(left_w, right_w)
            for r in range(height):
